const TEDED_SILK_ROAD_K_JJFZQNW_TRANSLATIONS = [
  `M\u1ed9t doanh nh\u00e2n \u1edf London g\u1eedi th\u00f4ng tin ch\u1ee9ng kho\u00e1n m\u1edbi nh\u1ea5t cho \u0111\u1ed3ng nghi\u1ec7p \u1edf H\u1ed3ng K\u00f4ng trong ch\u01b0a \u0111\u1ea7y m\u1ed9t gi\u00e2y.`,
  `Kh\u00e1ch h\u00e0ng \u1edf New York, M\u1ef9, \u0111\u1eb7t mua s\u1ea3n ph\u1ea9m \u0111i\u1ec7n t\u1eed s\u1ea3n xu\u1ea5t t\u1ea1i B\u1eafc Kinh ch\u1ec9 b\u1eb1ng m\u1ed9t c\u00fa nh\u1ea5p chu\u1ed9t.`,
  `Trong v\u00f2ng v\u00e0i ng\u00e0y, h\u00e0ng h\u00f3a \u0111\u00e3 \u0111\u01b0\u1ee3c v\u1eadn chuy\u1ec3n t\u1eeb \u0111\u1ea7u n\u00e0y sang \u0111\u1ea7u kia c\u1ee7a \u0111\u1ea1i d\u01b0\u01a1ng b\u1eb1ng m\u00e1y bay v\u1eadn t\u1ea3i ho\u1eb7c container \u0111\u01b0\u1eddng bi\u1ec3n.`,
  `Ng\u00e0y nay, t\u1ed1c \u0111\u1ed9 v\u00e0 t\u1ed5ng l\u01b0\u1ee3ng h\u00e0ng h\u00f3a v\u00e0 th\u00f4ng tin l\u01b0u chuy\u1ec3n to\u00e0n c\u1ea7u l\u00e0 ch\u01b0a t\u1eebng c\u00f3.`,
  `Nh\u01b0ng l\u1ecbch s\u1eed giao th\u01b0\u01a1ng to\u00e0n c\u1ea7u c\u1ed5 x\u01b0a h\u01a1n nhi\u1ec1u so v\u1edbi ch\u00fang ta t\u01b0\u1edfng.`,
  `2000 n\u0103m tr\u01b0\u1edbc, d\u1ecdc theo con \u0111\u01b0\u1eddng d\u00e0i 5000 d\u1eb7m,`,
  `t\u1ee9c l\u00e0 con \u0111\u01b0\u1eddng t\u01a1 l\u1ee5a n\u1ed5i ti\u1ebfng, ho\u1ea1t \u0111\u1ed9ng n\u00e0y \u0111\u00e3 b\u1eaft \u0111\u1ea7u.`,
  `Con \u0111\u01b0\u1eddng t\u01a1 l\u1ee5a kh\u00f4ng ch\u1ec9 l\u00e0 m\u1ed9t con \u0111\u01b0\u1eddng,`,
  `m\u00e0 l\u00e0 nhi\u1ec1u tuy\u1ebfn \u0111\u01b0\u1eddng \u0111an xen, d\u1ea7n h\u00ecnh th\u00e0nh qua nhi\u1ec1u th\u1ebf k\u1ef7.`,
  `T\u1eebng tuy\u1ebfn \u0111\u01b0\u1eddng d\u1eabn \u0111\u1ebfn nh\u1eefng n\u01a1i \u1edf kh\u00e1c nhau,`,
  `v\u00e0 c\u0169ng k\u1ebft n\u1ed1i ch\u00fang l\u1ea1i v\u1edbi nhau.`,
  `N\u1ec1n v\u0103n minh n\u00f4ng nghi\u1ec7p nguy\u00ean th\u1ee7y xu\u1ea5t hi\u1ec7n \u1edf c\u00e1c thung l\u0169ng s\u00f4ng m\u00e0u m\u1ee1 xa x\u00f4i,`,
  `\u0111\u1ecba h\u00ecnh b\u1ea5t ti\u1ec7n xung quanh v\u00e0 n\u1ed7i s\u1ee3 h\u00e3i nh\u1eefng \u0111i\u1ec1u ch\u01b0a bi\u1ebft \u0111\u00e3 c\u1ea3n tr\u1edf s\u1ef1 giao l\u01b0u c\u1ee7a ng\u01b0\u1eddi d\u00e2n \u0111\u1ecba ph\u01b0\u01a1ng.`,
  `Sau khi ng\u01b0\u1eddi d\u00e2n \u0111\u1ecba ph\u01b0\u01a1ng sinh s\u1ed1ng \u1edf \u0111\u00e2y m\u1ed9t th\u1eddi gian,`,
  `h\u1ecd ph\u00e1t hi\u1ec7n ra r\u1eb1ng nh\u1eefng g\u00ec h\u1ecd \u0111ang s\u1ed1ng trong sa m\u1ea1c kh\u00f4 c\u1eb1n v\u00e0 xung quanh bi\u00ean gi\u1edbi kh\u00f4ng ph\u1ea3i l\u00e0 ma qu\u1ef7 trong truy\u1ec1n thuy\u1ebft d\u00e2n gian,`,
  `m\u00e0 l\u00e0 c\u00e1c b\u1ed9 l\u1ea1c du m\u1ee5c tr\u00ean l\u01b0ng ng\u1ef1a.`,
  `Ng\u01b0\u1eddi Scythia tr\u00ean kh\u1eafp M\u00f4ng C\u1ed5 \u0111\u1ebfn Hungary,`,
  `\u0111\u00e3 s\u1edbm ti\u1ebfp x\u00fac v\u1edbi Hy L\u1ea1p,`,
  `Ai C\u1eadp, \u1ea4n \u0110\u1ed9 v\u00e0 Trung Qu\u1ed1c,`,
  `nh\u1eefng cu\u1ed9c ti\u1ebfp x\u00fac n\u00e0y th\u01b0\u1eddng kh\u00f4ng m\u1ea5y h\u00f2a b\u00ecnh.`,
  `Nh\u01b0ng ngay c\u1ea3 th\u00f4ng qua c\u00e1c cu\u1ed9c t\u1ea5n c\u00f4ng v\u00e0 chi\u1ebfn tranh,`,
  `c\u0169ng nh\u01b0 th\u01b0\u01a1ng m\u1ea1i v\u00e0 b\u1ea3o v\u1ec7 c\u00e1c th\u01b0\u01a1ng nh\u00e2n \u0111i l\u1ea1i \u0111\u1ec3 \u0111\u1ed5i l\u1ea5y thu\u1ebf quan,`,
  `c\u00e1c d\u00e2n t\u1ed9c du m\u1ee5c c\u0169ng b\u1eaft \u0111\u1ea7u truy\u1ec1n b\u00e1 h\u00e0ng h\u00f3a,`,
  `\u00fd t\u01b0\u1edfng v\u00e0 c\u00f4ng ngh\u1ec7 gi\u1eefa c\u00e1c n\u1ec1n v\u0103n h\u00f3a kh\u00f4ng c\u00f3 ti\u1ebfp x\u00fac tr\u1ef1c ti\u1ebfp.`,
  `Trong m\u1ea1ng l\u01b0\u1edbi ng\u00e0y c\u00e0ng m\u1edf r\u1ed9ng n\u00e0y,`,
  `m\u1ed9t trong nh\u1eefng tuy\u1ebfn \u0111\u01b0\u1eddng quan tr\u1ecdng nh\u1ea5t l\u00e0 con \u0111\u01b0\u1eddng ho\u00e0ng gia Ba T\u01b0.`,
  `Con \u0111\u01b0\u1eddng n\u00e0y \u0111\u01b0\u1ee3c Darius I ho\u00e0n th\u00e0nh v\u00e0o th\u1ebf k\u1ef7 th\u1ee9 5 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `n\u00f3 tr\u1ea3i d\u00e0i t\u1eeb s\u00f4ng Tigris \u0111\u1ebfn bi\u1ec3n Aegean,`,
  `d\u00e0i kho\u1ea3ng 2000 d\u1eb7m, h\u00e0ng h\u00f3a v\u00e0 th\u00f4ng tin trong \u0111\u00f3 ch\u1ec9 m\u1ea5t m\u1ed9t ph\u1ea7n m\u01b0\u1eddi th\u1eddi gian so v\u1edbi m\u1ed9t l\u1eef kh\u00e1ch c\u00e1 nh\u00e2n.`,
  `Sau \u0111\u00f3, Alexander \u0110\u1ea1i \u0111\u1ebf chinh ph\u1ee5c Ba T\u01b0,`,
  `B\u1eb1ng c\u00e1ch chi\u1ebfm \u0111\u00f3ng c\u00e1c th\u00e0nh ph\u1ed1 nh\u01b0 Samarkand,`,
  `l\u00e3nh th\u1ed5 c\u1ee7a \u00f4ng \u0111\u00e3 m\u1edf r\u1ed9ng \u0111\u1ebfn t\u1eadn Trung \u00c1.`,
  `Ngo\u00e0i ra, \u00f4ng c\u00f2n th\u00e0nh l\u1eadp c\u00e1c th\u00e0nh ph\u1ed1 m\u1edbi nh\u01b0 Khujand.`,
  `Nh\u1eefng n\u1ec1n v\u0103n minh v\u00e0 m\u1ea1ng l\u01b0\u1edbi th\u01b0\u01a1ng m\u1ea1i c\u1ee7a Hy L\u1ea1p, Ai C\u1eadp, Ba T\u01b0 v\u00e0 \u1ea4n \u0110\u1ed9 \u0111\u00e3 m\u1edf r\u1ed9ng v\u1ec1 ph\u00eda \u0111\u00f4ng t\u1edbi m\u1ee9c l\u1edbn nh\u1ea5t trong l\u1ecbch s\u1eed,`,
  `t\u1ea1o n\u1ec1n t\u1ea3ng cho c\u1ea7u n\u1ed1i giao ti\u1ebfp gi\u1eefa Trung Qu\u1ed1c v\u00e0 ph\u01b0\u01a1ng T\u00e2y.`,
  `M\u00e3i \u0111\u1ebfn th\u1ebf k\u1ef7 th\u1ee9 2 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `m\u1ed9t s\u1ee9 gi\u1ea3 t\u00ean l\u00e0 Tr\u01b0\u01a1ng Khi\u00ean \u0111\u01b0\u1ee3c ph\u00e1i \u0111i \u0111\u00e0m ph\u00e1n v\u1edbi c\u00e1c b\u1ed9 l\u1ea1c du m\u1ee5c ph\u00eda t\u00e2y.`,
  `Sau khi tr\u1edf v\u1ec1 Trung Qu\u1ed1c, v\u1ecb s\u1ee9 gi\u1ea3 n\u00e0y \u0111\u00e3 k\u1ec3 cho H\u00e1n V\u0169 \u0110\u1ebf nghe nhi\u1ec1u c\u00e2u chuy\u1ec7n v\u1ec1 c\u00e1c n\u1ec1n v\u0103n minh c\u1ed5 \u0111\u1ea1i,`,
  `th\u01b0\u01a1ng m\u1ea1i th\u1ecbnh v\u01b0\u1ee3ng v\u00e0 h\u00e0ng h\u00f3a k\u1ef3 l\u1ea1 \u1edf c\u00e1c v\u00f9ng l\u00e3nh th\u1ed5 ph\u00eda t\u00e2y bi\u00ean gi\u1edbi c\u1ee7a \u00f4ng.`,
  `Sau \u0111\u00f3, nhi\u1ec1u s\u1ee9 gi\u1ea3`,
  `v\u00e0 th\u01b0\u01a1ng nh\u00e2n li\u00ean t\u1ee5c \u0111\u01b0\u1ee3c ph\u00e1i \u0111\u1ebfn Ba T\u01b0 v\u00e0 \u1ea4n \u0110\u1ed9,`,
  `trao \u0111\u1ed5i l\u1ee5a v\u00e0 ng\u1ecdc \u0111\u1ec3 l\u1ea5y ng\u1ef1a v\u00e0 b\u00f4ng c\u1ee7a h\u1ecd.`,
  `Qu\u00e2n \u0111\u1ed9i c\u0169ng \u0111i theo \u0111\u1ec3 \u0111\u1ea3m b\u1ea3o an to\u00e0n cho h\u00e0nh tr\u00ecnh c\u1ee7a h\u1ecd.`,
  `Con \u0111\u01b0\u1eddng gi\u1eefa ph\u01b0\u01a1ng \u0110\u00f4ng v\u00e0 ph\u01b0\u01a1ng T\u00e2y d\u1ea7n h\u00ecnh th\u00e0nh m\u1ed9t m\u1ea1ng l\u01b0\u1edbi xuy\u00ean \u00c2u-\u00c1,`,
  `m\u1ea1ng l\u01b0\u1edbi n\u00e0y gi\u00fap cho giao l\u01b0u v\u0103n h\u00f3a v\u00e0 th\u01b0\u01a1ng m\u1ea1i gi\u1eefa \u00c2u-\u00c1 \u0111\u1ea1t m\u1ee9c cao nh\u1ea5t trong l\u1ecbch s\u1eed l\u00fac b\u1ea5y gi\u1edd.`,
  `H\u00e0ng h\u00f3a Trung Qu\u1ed1c du nh\u1eadp v\u00e0o La M\u00e3,`,
  `g\u00e2y ra t\u00ecnh tr\u1ea1ng ch\u1ea3y m\u00e1u v\u00e0ng nghi\u00eam tr\u1ecdng,`,
  `do \u0111\u00f3 La M\u00e3 \u0111\u00e3 c\u1ea5m giao d\u1ecbch t\u01a1 l\u1ee5a.`,
  `\u0110\u1ed3 th\u1ee7y tinh La M\u00e3 c\u0169ng r\u1ea5t \u0111\u01b0\u1ee3c \u01b0a chu\u1ed9ng \u1edf Trung Qu\u1ed1c.`,
  `Qu\u00e2n vi\u1ec5n chinh Trung \u00c1 \u0111\u00e3 ch\u1ee9ng ki\u1ebfn cu\u1ed9c g\u1eb7p g\u1ee1 gi\u1eefa qu\u00e2n \u0111\u1ed9i Trung Qu\u1ed1c v\u00e0 La M\u00e3,`,
  `th\u1eadm ch\u00ed c\u00f3 th\u1ec3 \u0111\u00e3 truy\u1ec1n b\u00e1 k\u1ef9 thu\u1eadt n\u1ecf sang ph\u01b0\u01a1ng T\u00e2y.`,
  `Nhu c\u1ea7u v\u1ec1 h\u00e0ng h\u00f3a ngo\u1ea1i qu\u1ed1c,`,
  `l\u1ee3i \u00edch t\u1eeb th\u01b0\u01a1ng m\u1ea1i \u0111\u00e3 gi\u1eef cho Con \u0111\u01b0\u1eddng T\u01a1 l\u1ee5a n\u00e0y lu\u00f4n \u0111\u01b0\u1ee3c b\u1ea3o t\u1ed3n.`,
  `M\u1eb7c d\u00f9 \u0110\u1ebf ch\u1ebf La M\u00e3 s\u1ee5p \u0111\u1ed5, c\u00e1c tri\u1ec1u \u0111\u1ea1i Trung Qu\u1ed1c h\u01b0ng th\u1ecbnh r\u1ed3i suy t\u00e0n,`,
  `ngay c\u1ea3 nh\u1eefng th\u01b0\u01a1ng nh\u00e2n M\u00f4ng C\u1ed5 n\u1ed5i ti\u1ebfng v\u1edbi vi\u1ec7c c\u01b0\u1edb b\u00f3c v\u00e0 t\u00edch tr\u1eef c\u1ee7a c\u1ea3i c\u0169ng t\u00edch c\u1ef1c b\u1ea3o v\u1ec7 c\u00e1c tuy\u1ebfn \u0111\u01b0\u1eddng th\u01b0\u01a1ng m\u1ea1i n\u00e0y,`,
  `ch\u1ee9 kh\u00f4ng ph\u1ea3i ph\u00e1 h\u1ee7y ch\u00fang.`,
  `V\u1edbi s\u1ef1 ph\u00e1t tri\u1ec3n c\u1ee7a n\u1ec1n kinh t\u1ebf h\u00e0ng h\u00f3a, con \u0111\u01b0\u1eddng n\u00e0y \u0111\u1ed3ng th\u1eddi gi\u00fap v\u0103n h\u00f3a,`,
  `c\u00f4ng ngh\u1ec7 ti\u00ean ti\u1ebfn, t\u01b0 t\u01b0\u1edfng v\u00e0 ng\u00f4n ng\u1eef \u0111\u01b0\u1ee3c l\u01b0u th\u00f4ng.`,
  `Kh\u1edfi ngu\u1ed3n t\u1eeb \u1ea4n \u0110\u1ed9,`,
  `Ph\u1eadt gi\u00e1o \u0111\u00e3 truy\u1ec1n b\u00e1 \u0111\u1ebfn Trung Qu\u1ed1c v\u00e0 Nh\u1eadt B\u1ea3n,`,
  `tr\u1edf th\u00e0nh t\u00f4n gi\u00e1o ph\u1ed5 bi\u1ebfn nh\u1ea5t \u1edf ch\u00e2u \u00c1.`,
  `H\u1ed3i gi\u00e1o t\u1eeb b\u00e1n \u0111\u1ea3o \u1ea2 R\u1eadp truy\u1ec1n \u0111\u1ebfn Nam \u00c1,`,
  `v\u00e0 k\u1ebft h\u1ee3p v\u1edbi t\u00edn ng\u01b0\u1ee1ng \u0111\u1ecba ph\u01b0\u01a1ng h\u00ecnh th\u00e0nh c\u00e1c t\u00f4n gi\u00e1o m\u1edbi,`,
  `nh\u01b0 \u0111\u1ea1o Sikh.`,
  `Thu\u1ed1c s\u00fang t\u1eeb Trung Qu\u1ed1c truy\u1ec1n \u0111\u1ebfn Trung \u0110\u00f4ng,`,
  `\u0111\u1ecbnh h\u00ecnh t\u01b0\u01a1ng lai c\u1ee7a \u0110\u1ebf qu\u1ed1c Ottoman,`,
  `\u0110\u1ebf qu\u1ed1c Safavid v\u00e0 \u0110\u1ebf qu\u1ed1c Maratha.`,
  `\u1ede m\u1ed9t m\u1ee9c \u0111\u1ed9 n\u00e0o \u0111\u00f3,`,
  `Con \u0111\u01b0\u1eddng T\u01a1 l\u1ee5a \u0111\u00e3 t\u1ef1 k\u1ebft th\u00fac vai tr\u00f2 c\u1ee7a m\u00ecnh.`,
  `K\u0129 thu\u1eadt h\u00e0ng h\u1ea3i m\u1edbi nh\u01b0 la b\u00e0n truy\u1ec1n \u0111\u1ebfn ch\u00e2u \u00c2u,`,
  `khi\u1ebfn c\u00e1c tuy\u1ebfn \u0111\u01b0\u1eddng b\u1ed9 d\u00e0i tr\u00ean \u0111\u1ea5t li\u1ec1n b\u1ecb lo\u1ea1i b\u1ecf.`,
  `\u0110\u1ed3ng th\u1eddi, sau khi nh\u00e0 Nguy\u00ean s\u1ee5p \u0111\u1ed5, Trung Qu\u1ed1c bi\u1ebfn m\u1ea5t kh\u1ecfi b\u1ea3n \u0111\u1ed3 th\u01b0\u01a1ng m\u1ea1i qu\u1ed1c t\u1ebf.`,
  `M\u1eb7c d\u00f9 c\u00e1c tuy\u1ebfn \u0111\u01b0\u1eddng v\u00e0 m\u1ea1ng l\u01b0\u1edbi th\u01b0\u01a1ng m\u1ea1i c\u0169 kh\u00f4ng t\u1ed3n t\u1ea1i l\u00e2u d\u00e0i,`,
  `ch\u00fang \u0111\u00e3 v\u0129nh vi\u1ec5n thay \u0111\u1ed5i th\u1ebf gi\u1edbi,`,
  `kh\u00f4ng c\u00f2n kh\u1ea3 n\u0103ng quay ng\u01b0\u1ee3c tr\u1edf l\u1ea1i.`,
  `Ng\u01b0\u1eddi ch\u00e2u \u00c2u t\u00ecm ki\u1ebfm nh\u1eefng tuy\u1ebfn \u0111\u01b0\u1eddng bi\u1ec3n m\u1edbi,`,
  `mong mu\u1ed1n t\u00ecm ki\u1ebfm s\u1ef1 gi\u00e0u c\u00f3 \u1edf \u0110\u00f4ng \u00c1,`,
  `d\u1eabn \u0111\u1ebfn vi\u1ec7c h\u1ecd th\u00e1m hi\u1ec3m v\u00e0 m\u1edf r\u1ed9ng \u1edf ch\u00e2u Phi v\u00e0 ch\u00e2u M\u1ef9.`,
  `Ng\u00e0y nay, s\u1ef1 k\u1ebft n\u1ed1i kh\u00f4ng ng\u1eebng gi\u1eefa c\u00e1c qu\u1ed1c gia tr\u00ean to\u00e0n c\u1ea7u \u0111ang \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn cu\u1ed9c s\u1ed1ng c\u1ee7a ch\u00fang ta.`,
  `Ng\u01b0\u1eddi ti\u00eau d\u00f9ng Canada mua \u00e1o ph\u00f4ng s\u1ea3n xu\u1ea5t t\u1ea1i Bangladesh,`,
  `kh\u00e1n gi\u1ea3 Nh\u1eadt B\u1ea3n xem c\u00e1c ch\u01b0\u01a1ng tr\u00ecnh truy\u1ec1n h\u00ecnh c\u1ee7a Anh,`,
  `v\u00e0 ng\u01b0\u1eddi Tunisia s\u1eed d\u1ee5ng ph\u1ea7n m\u1ec1m c\u1ee7a M\u1ef9 \u0111\u1ec3 t\u1ed5 ch\u1ee9c c\u00e1ch m\u1ea1ng.`,
  `\u1ea2nh h\u01b0\u1edfng v\u0103n h\u00f3a v\u00e0 kinh t\u1ebf c\u1ee7a to\u00e0n c\u1ea7u h\u00f3a l\u00e0 kh\u00f4ng th\u1ec3 ph\u1ee7 nh\u1eadn,`,
  `nh\u01b0ng nh\u1eefng l\u1ee3i \u00edch v\u00e0 h\u1ea1n ch\u1ebf \u0111i k\u00e8m c\u0169ng kh\u00f4ng c\u00f2n l\u00e0 \u0111i\u1ec1u m\u1edbi m\u1ebb.`,
  `M\u1eb7c d\u00f9 nh\u1eefng d\u00e3y n\u00fai,`,
  `sa m\u1ea1c v\u00e0 \u0111\u1ea1i d\u01b0\u01a1ng t\u1eebng ng\u0103n c\u00e1ch ch\u00fang ta hi\u1ec7n \u0111\u00e3 \u0111\u01b0\u1ee3c v\u01b0\u1ee3t qua b\u1eb1ng m\u00e1y bay si\u00eau thanh,`,
  `c\u00e1p li\u00ean l\u1ea1c xuy\u00ean l\u1ee5c \u0111\u1ecba v\u00e0 t\u00edn hi\u1ec7u truy\u1ec1n qua kh\u00f4ng gian,`,
  `kh\u00f4ng c\u00f2n c\u1ea7n \u0111\u1ebfn nh\u1eefng \u0111o\u00e0n l\u1eef h\u00e0nh m\u1ea5t h\u00e0ng th\u00e1ng tr\u1eddi, nh\u01b0ng t\u1ea5t c\u1ea3 nh\u1eefng \u0111i\u1ec1u n\u00e0y s\u1ebd kh\u00f4ng th\u1ec3 th\u1ef1c hi\u1ec7n \u0111\u01b0\u1ee3c n\u1ebfu kh\u00f4ng c\u00f3 m\u1ed9t n\u1ec1n v\u0103n h\u00f3a ti\u00ean phong.`,
  `\u0110i\u1ec1u n\u00e0y kh\u00f4ng th\u1ec3 th\u1ef1c hi\u1ec7n \u0111\u01b0\u1ee3c.`,
  `N\u1ec1n v\u0103n h\u00f3a ti\u00ean ti\u1ebfn nh\u01b0 v\u1eady \u0111\u00e3 t\u1ea1o ra Con \u0111\u01b0\u1eddng t\u01a1 l\u1ee5a,`,
  `M\u1ea1ng internet \u0111\u1ea7u ti\u00ean tr\u00ean th\u1ebf gi\u1edbi k\u1ebft n\u1ed1i v\u1ea1n v\u1eadt.`,
  `N\u1ebfu b\u1ea1n y\u00eau th\u00edch vi\u1ec7c h\u1ecdc h\u1ecfi,`,
  `h\u00e3y \u0111\u0103ng k\u00fd k\u00eanh ch\u00fang t\u00f4i.`,
  `Ch\u00fang t\u00f4i \u0111\u0103ng t\u1ea3i nhi\u1ec1u n\u1ed9i dung video m\u1edbi m\u1ebb v\u00e0 \u0111a d\u1ea1ng,`,
  `t\u1eeb vi\u1ec7c nh\u00ecn nh\u1eadn l\u1ecbch s\u1eed th\u1ebf gi\u1edbi qua \u0111\u00f4i m\u1eaft lo\u00e0i m\u00e8o,`,
  `\u0111\u1ebfn nh\u1eefng k\u1ef9 n\u0103ng c\u1ea7n thi\u1ebft \u0111\u1ec3 sinh t\u1ed3n tr\u00ean m\u1eb7t tr\u0103ng,`,
  `v\u00e0 nhi\u1ec1u h\u01a1n th\u1ebf n\u1eefa. H\u00e3y ti\u1ebfp t\u1ee5c theo d\u00f5i,`,
  `v\u00e0 gi\u1eef v\u1eefng tinh th\u1ea7n kh\u00e1m ph\u00e1!`,
];

