const TEDED_VOTING_SYSTEM_RSEF5ESXG_W_TRANSLATIONS = [
  `N\u1ebfu ch\u00fang ta mu\u1ed1n th\u00e0nh l\u1eadp m\u1ed9t s\u00e2n bay v\u0169 tr\u1ee5 m\u1edbi t\u1ea1i b\u1ed1n c\u0103n c\u1ee9 Sao H\u1ecfa g\u1ea7n \u0111\u00e2y nh\u1ea5t,`,
  `V\u00e0 b\u1ecf phi\u1ebfu \u0111\u1ec3 quy\u1ebft \u0111\u1ecbnh \u0111\u1ecba \u0111i\u1ec3m c\u1ee7a s\u00e2n bay v\u0169 tr\u1ee5 m\u1edbi.`,
  `Trong s\u1ed1 100 c\u01b0 d\u00e2n thu\u1ed9c \u0111\u1ecba tr\u00ean Sao H\u1ecfa,`,
  `42 ng\u01b0\u1eddi s\u1ed1ng \u1edf c\u0103n c\u1ee9 ph\u00eda T\u00e2y,`,
  `26 ng\u01b0\u1eddi s\u1ed1ng \u1edf c\u0103n c\u1ee9 ph\u00eda B\u1eafc,`,
  `15 ng\u01b0\u1eddi s\u1ed1ng \u1edf c\u0103n c\u1ee9 ph\u00eda Nam,`,
  `17 ng\u01b0\u1eddi s\u1ed1ng \u1edf c\u0103n c\u1ee9 ph\u00eda \u0110\u00f4ng.`,
  `V\u1edbi m\u1ee5c \u0111\u00edch n\u00e0y,`,
  `Gi\u1ea3 s\u1eed t\u1ea5t c\u1ea3 m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u mu\u1ed1n s\u00e2n bay v\u0169 tr\u1ee5 c\u00e0ng g\u1ea7n c\u0103n c\u1ee9 c\u1ee7a h\u1ecd c\u00e0ng t\u1ed1t,`,
  `V\u00e0 s\u1ebd b\u1ecf phi\u1ebfu d\u1ef1a tr\u00ean \u0111i\u1ec1u n\u00e0y.`,
  `L\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 t\u1ed5 ch\u1ee9c m\u1ed9t cu\u1ed9c b\u1ecf phi\u1ebfu c\u00f4ng b\u1eb1ng nh\u1ea5t?`,
  `Gi\u1ea3i ph\u00e1p tr\u1ef1c ti\u1ebfp nh\u1ea5t l\u00e0 m\u1ed7i ng\u01b0\u1eddi b\u1ecf m\u1ed9t phi\u1ebfu,`,
  `Sau \u0111\u00f3 ch\u1ecdn \u0111\u1ecba \u0111i\u1ec3m c\u00f3 nhi\u1ec1u phi\u1ebfu nh\u1ea5t.`,
  `\u0110\u00e2y l\u00e0 ch\u1ebf \u0111\u1ed9 \u0111a s\u1ed1,`,
  `Ho\u1eb7c ng\u01b0\u1eddi d\u1eabn \u0111\u1ea7u s\u1ebd th\u1eafng c\u1eed.`,
  `Trong tr\u01b0\u1eddng h\u1ee3p n\u00e0y,`,
  `C\u0103n c\u1ee9 ph\u00eda T\u00e2y d\u1ec5 d\u00e0ng th\u1eafng cu\u1ed9c,`,
  `v\u00ec c\u00f3 nhi\u1ec1u c\u01b0 d\u00e2n h\u01a1n c\u00e1c c\u0103n c\u1ee9 kh\u00e1c.`,
  `Tuy nhi\u00ean, h\u1ea7u h\u1ebft c\u01b0 d\u00e2n s\u1ebd coi \u0111\u00e2y l\u00e0 k\u1ebft qu\u1ea3 t\u1ed3i t\u1ec7 nh\u1ea5t`,
  `v\u00ec c\u0103n c\u1ee9 ph\u00eda T\u00e2y r\u1ea5t xa nh\u1eefng ng\u01b0\u1eddi c\u00f2n l\u1ea1i.`,
  `V\u1eady, b\u1ea7u c\u1eed \u0111a s\u1ed1 c\u00f3 th\u1ef1c s\u1ef1 l\u00e0 ph\u01b0\u01a1ng ph\u00e1p c\u00f4ng b\u1eb1ng nh\u1ea5t?`,
  `Ch\u00fang ta c\u00f3 th\u1ec3 th\u1eed b\u1ecf phi\u1ebfu l\u1ef1a ch\u1ecdn theo x\u1ebfp h\u1ea1ng,`,
  `t\u1ee9c l\u00e0 xem x\u00e9t t\u1ea5t c\u1ea3 c\u00e1c \u01b0u ti\u00ean c\u1ee7a m\u1ecdi ng\u01b0\u1eddi,`,
  `ch\u1ee9 kh\u00f4ng ch\u1ec9 l\u1ef1a ch\u1ecdn \u0111\u1ea7u ti\u00ean c\u1ee7a h\u1ecd?`,
  `Lu\u1eadt b\u1ecf phi\u1ebfu l\u1ef1a ch\u1ecdn theo x\u1ebfp h\u1ea1ng nh\u01b0 sau:`,
  `Tr\u01b0\u1edbc ti\u00ean, c\u1eed tri s\u1ebd x\u1ebfp h\u1ea1ng c\u00e1c l\u1ef1a ch\u1ecdn c\u1ee7a h\u1ecd theo th\u1ee9 t\u1ef1 \u01b0u ti\u00ean,`,
  `ch\u00fang ta s\u1ebd so s\u00e1nh l\u1ef1a ch\u1ecdn \u0111\u1ea7u ti\u00ean c\u1ee7a h\u1ecd.`,
  `C\u0103n c\u1ee9 ph\u00eda Nam nh\u1eadn \u0111\u01b0\u1ee3c \u00edt phi\u1ebfu nh\u1ea5t,`,
  `n\u00ean s\u1ebd b\u1ecb lo\u1ea1i \u0111\u1ea7u ti\u00ean.`,
  `15 phi\u1ebfu b\u1ea7u cho c\u0103n c\u1ee9 n\u00e0y s\u1ebd \u0111\u01b0\u1ee3c ph\u00e2n b\u1ed5 l\u1ea1i cho l\u1ef1a ch\u1ecdn th\u1ee9 hai c\u1ee7a c\u1eed tri,`,
  `c\u0103n c\u1ee9 ph\u00eda \u0111\u00f4ng. T\u1ed5ng s\u1ed1 phi\u1ebfu c\u1ee7a n\u00f3 s\u1ebd l\u00e0 32.`,
  `Sau \u0111\u00f3, ch\u00fang ta l\u1ea1i so s\u00e1nh,`,
  `ch\u1ecdn ra ng\u01b0\u1eddi \u0111\u1ee9ng \u0111\u1ea7u v\u00e0 lo\u1ea1i b\u1ecf ng\u01b0\u1eddi cu\u1ed1i c\u00f9ng.`,
  `L\u1ea7n n\u00e0y c\u0103n c\u1ee9 ph\u00eda b\u1eafc s\u1ebd b\u1ecb lo\u1ea1i.`,
  `L\u1ef1a ch\u1ecdn th\u1ee9 hai c\u1ee7a c\u01b0 d\u00e2n c\u0103n c\u1ee9 n\u00e0y l\u1ebd ra l\u00e0 c\u0103n c\u1ee9 ph\u00eda nam,`,
  `nh\u01b0ng c\u0103n c\u1ee9 ph\u00eda nam \u0111\u00e3 b\u1ecb lo\u1ea1i,`,
  `s\u1ed1 phi\u1ebfu s\u1ebd \u0111\u01b0\u1ee3c ph\u00e2n b\u1ed5 cho l\u1ef1a ch\u1ecdn th\u1ee9 ba c\u1ee7a h\u1ecd.`,
  `Nh\u01b0 v\u1eady, c\u0103n c\u1ee9 ph\u00eda \u0111\u00f4ng c\u00f3 58 phi\u1ebfu,`,
  `so v\u1edbi 42 phi\u1ebfu c\u1ee7a c\u0103n c\u1ee9 ph\u00eda t\u00e2y,`,
  `c\u0103n c\u1ee9 ph\u00eda \u0111\u00f4ng th\u1eafng.`,
  `Nh\u01b0ng \u0111i\u1ec1u n\u00e0y d\u01b0\u1eddng nh\u01b0 c\u0169ng kh\u00f4ng c\u00f4ng b\u1eb1ng l\u1eafm.`,
  `C\u0103n c\u1ee9 ph\u00eda \u0111\u00f4ng kh\u00f4ng ch\u1ec9 \u0111\u1ee9ng th\u1ee9 hai t\u1eeb d\u01b0\u1edbi l\u00ean ngay t\u1eeb \u0111\u1ea7u,`,
  `m\u00e0 c\u00f2n n\u1eb1m trong hai v\u1ecb tr\u00ed cu\u1ed1i c\u00f9ng trong x\u1ebfp h\u1ea1ng c\u1ee7a h\u1ea7u h\u1ebft m\u1ecdi ng\u01b0\u1eddi.`,
  `Tuy nhi\u00ean, ch\u00fang ta c\u0169ng c\u00f3 th\u1ec3 kh\u00f4ng d\u00f9ng x\u1ebfp h\u1ea1ng,`,
  `m\u00e0 th\u1eed d\u00f9ng b\u1ecf phi\u1ebfu nhi\u1ec1u v\u00f2ng.`,
  `Hai l\u1ef1a ch\u1ecdn \u0111\u1ee9ng \u0111\u1ea7u s\u1ebd ti\u1ebfp t\u1ee5c v\u00e0o v\u00f2ng chung k\u1ebft ri\u00eang.`,
  `Th\u00f4ng th\u01b0\u1eddng, \u0111i\u1ec1u n\u00e0y c\u00f3 ngh\u0129a l\u00e0 Khu T\u00e2y v\u00e0 Khu B\u1eafc th\u1eafng \u1edf v\u00f2ng m\u1ed9t,`,
  `v\u00e0 Khu B\u1eafc th\u1eafng \u1edf v\u00f2ng hai.`,
  `Nh\u01b0ng c\u01b0 d\u00e2n Khu \u0110\u00f4ng nh\u1eadn ra r\u1eb1ng,`,
  `m\u1eb7c d\u00f9 s\u1ed1 phi\u1ebfu c\u1ee7a h\u1ecd kh\u00f4ng \u0111\u1ee7 \u0111\u1ec3 h\u1ecd chi\u1ebfn th\u1eafng,`,
  `h\u1ecd v\u1eabn c\u00f3 th\u1ec3 l\u00e0m cho k\u1ebft qu\u1ea3 nghi\u00eang v\u1ec1 ph\u00eda h\u1ecd mong mu\u1ed1n.`,
  `\u1ede v\u00f2ng m\u1ed9t, h\u1ecd b\u1ecf phi\u1ebfu cho Khu Nam, thay v\u00ec Khu \u0110\u00f4ng c\u1ee7a ch\u00ednh h\u1ecd,`,
  `\u0111\u1ec3 ng\u0103n Khu B\u1eafc gi\u00e0nh chi\u1ebfn th\u1eafng th\u00e0nh c\u00f4ng.`,
  `V\u00ec phi\u1ebfu b\u1ea7u chi\u1ebfn l\u01b0\u1ee3c c\u1ee7a c\u01b0 d\u00e2n Khu \u0110\u00f4ng,`,
  `m\u1eb7c d\u00f9 c\u00f3 \u00edt c\u01b0 d\u00e2n nh\u1ea5t,`,
  `Khu Nam \u0111\u00e3 d\u1ec5 d\u00e0ng chi\u1ebfn th\u1eafng \u1edf v\u00f2ng hai.`,
  `N\u1ebfu m\u1ed9t h\u1ec7 th\u1ed1ng khuy\u1ebfn kh\u00edch khai b\u00e1o sai s\u1edf th\u00edch,`,
  `li\u1ec7u n\u00f3 c\u00f3 c\u00f2n \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 m\u1ed9t h\u1ec7 th\u1ed1ng c\u00f4ng b\u1eb1ng kh\u00f4ng?`,
  `C\u00f3 l\u1ebd ch\u00fang ta c\u1ea7n y\u00eau c\u1ea7u c\u1eed tri \u0111\u01b0a ra l\u1ef1a ch\u1ecdn cho t\u1ea5t c\u1ea3 c\u00e1c c\u1eb7p \u0111\u00f4i c\u00f3 th\u1ec3 c\u00f3,`,
  `t\u1eeb \u0111\u00f3 ch\u1ecdn ra s\u1edf th\u00edch c\u1ee7a h\u1ecd.`,
  `\u0110\u00e2y l\u00e0 ph\u01b0\u01a1ng ph\u00e1p Condorcet,`,
  `hay c\u00f2n g\u1ecdi l\u00e0 h\u1ec7 th\u1ed1ng x\u1ebfp h\u1ea1ng \u0111\u00f4i. V\u00ed d\u1ee5,`,
  `C\u0103n c\u1ee9 T\u00e2y \u0111\u1ed1i \u0111\u1ea7u C\u0103n c\u1ee9 B\u1eafc,`,
  `t\u1ea5t c\u1ea3 100 c\u01b0 d\u00e2n thu\u1ed9c \u0111\u1ecba ph\u1ea3i ch\u1ecdn \u01b0u ti\u00ean c\u1ee7a h\u1ecd gi\u1eefa hai c\u0103n c\u1ee9 n\u00e0y.`,
  `K\u1ebft qu\u1ea3 l\u00e0 C\u0103n c\u1ee9 T\u00e2y \u0111\u01b0\u1ee3c 42 phi\u1ebfu v\u00e0 C\u0103n c\u1ee9 B\u1eafc \u0111\u01b0\u1ee3c 58 phi\u1ebfu,`,
  `v\u00ec ba c\u0103n c\u1ee9 c\u00f2n l\u1ea1i \u0111\u1ec1u nghi\u00eang v\u1ec1 ph\u00eda B\u1eafc.`,
  `B\u00e2y gi\u1edd quy tr\u00ecnh t\u01b0\u01a1ng t\u1ef1 \u0111\u01b0\u1ee3c th\u1ef1c hi\u1ec7n cho n\u0103m c\u1eb7p c\u00f2n l\u1ea1i,`,
  `ng\u01b0\u1eddi chi\u1ebfn th\u1eafng s\u1ebd l\u00e0 c\u0103n c\u1ee9 th\u1eafng nhi\u1ec1u nh\u1ea5t.`,
  `C\u0103n c\u1ee9 B\u1eafc th\u1eafng ba l\u1ea7n,`,
  `C\u0103n c\u1ee9 Nam th\u1eafng hai l\u1ea7n.`,
  `Ch\u00fang th\u1ef1c s\u1ef1 l\u00e0 nh\u1eefng \u0111\u1ecba \u0111i\u1ec3m g\u1ea7n trung t\u00e2m nh\u1ea5t,`,
  `v\u00e0 l\u1ee3i th\u1ebf c\u1ee7a C\u0103n c\u1ee9 B\u1eafc l\u00e0,`,
  `n\u00f3 kh\u00f4ng ph\u1ea3i l\u00e0 l\u1ef1a ch\u1ecdn b\u1ecb lo\u1ea1i tr\u1eeb nhi\u1ec1u nh\u1ea5t c\u1ee7a b\u1ea5t k\u1ef3 b\u00ean n\u00e0o.`,
  `V\u1eady, \u0111i\u1ec1u n\u00e0y c\u00f3 ngh\u0129a l\u00e0 ph\u01b0\u01a1ng ph\u00e1p Condorcet lu\u00f4n l\u00e0 h\u1ec7 th\u1ed1ng b\u1ecf phi\u1ebfu l\u00fd t\u01b0\u1edfng nh\u1ea5t?`,
  `Kh\u00f4ng h\u1eb3n v\u1eady. Gi\u1ea3 s\u1eed c\u00f3 ba \u1ee9ng c\u1eed vi\u00ean trong m\u1ed9t cu\u1ed9c b\u1ea7u c\u1eed,`,
  `N\u1ebfu c\u1eed tri th\u00edch A h\u01a1n B,`,
  `th\u00edch B h\u01a1n C, nh\u01b0ng l\u1ea1i th\u00edch C h\u01a1n A,`,
  `th\u00ec ph\u01b0\u01a1ng ph\u00e1p n\u00e0y s\u1ebd kh\u00f4ng th\u1ec3 ch\u1ecdn ra ng\u01b0\u1eddi chi\u1ebfn th\u1eafng.`,
  `Trong nhi\u1ec1u th\u1eadp k\u1ef7, c\u00e1c nh\u00e0 nghi\u00ean c\u1ee9u v\u00e0 th\u1ed1ng k\u00ea h\u1ecdc \u0111\u00e3 \u0111\u1ec1 xu\u1ea5t h\u00e0ng ch\u1ee5c ph\u01b0\u01a1ng ph\u00e1p ph\u1ee9c t\u1ea1p \u0111\u1ec3 b\u1ecf phi\u1ebfu v\u00e0 ki\u1ec3m phi\u1ebfu,`,
  `th\u1eadm ch\u00ed m\u1ed9t s\u1ed1 \u0111\u00e3 \u0111\u01b0\u1ee3c \u00e1p d\u1ee5ng v\u00e0o th\u1ef1c t\u1ebf.`,
  `Nh\u01b0ng d\u00f9 b\u1ea1n ch\u1ecdn ph\u01b0\u01a1ng ph\u00e1p n\u00e0o, v\u1eabn c\u00f3 th\u1ec3 t\u01b0\u1edfng t\u01b0\u1ee3ng ra nh\u1eefng tr\u01b0\u1eddng h\u1ee3p k\u1ebft qu\u1ea3 kh\u00f4ng c\u00f4ng b\u1eb1ng.`,
  `Th\u1ef1c ra, quan ni\u1ec7m tr\u1ef1c gi\u00e1c c\u1ee7a ch\u00fang ta v\u1ec1 s\u1ef1 c\u00f4ng b\u1eb1ng \u0111\u00e3 bao g\u1ed3m m\u1ed9t s\u1ed1 gi\u1ea3 \u0111\u1ecbnh c\u00f3 th\u1ec3 m\u00e2u thu\u1eabn v\u1edbi nhau.`,
  `N\u1ebfu \u1ea3nh h\u01b0\u1edfng c\u1ee7a m\u1ed9t s\u1ed1 c\u1eed tri l\u1edbn h\u01a1n nh\u1eefng ng\u01b0\u1eddi kh\u00e1c,`,
  `c\u00f3 v\u1ebb nh\u01b0 kh\u00f4ng c\u00f4ng b\u1eb1ng.`,
  `Nh\u01b0ng vi\u1ec7c b\u1ecf qua s\u1edf th\u00edch c\u1ee7a thi\u1ec3u s\u1ed1,`,
  `ho\u1eb7c khuy\u1ebfn kh\u00edch c\u1eed tri l\u1ee3i d\u1ee5ng h\u1ec7 th\u1ed1ng \u0111\u1ec3 gian l\u1eadn,`,
  `c\u0169ng c\u00f3 v\u1ebb kh\u00f4ng c\u00f4ng b\u1eb1ng.`,
  `Th\u1ef1c t\u1ebf, \u0111\u00e3 c\u00f3 ch\u1ee9ng minh to\u00e1n h\u1ecdc ch\u1ec9 ra r\u1eb1ng,`,
  `ch\u1ec9 c\u1ea7n cu\u1ed9c b\u1ea7u c\u1eed c\u00f3 nhi\u1ec1u h\u01a1n hai l\u1ef1a ch\u1ecdn,`,
  `th\u00ec b\u1ea5t k\u1ef3 h\u1ec7 th\u1ed1ng b\u1ecf phi\u1ebfu n\u00e0o \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf c\u0169ng s\u1ebd vi ph\u1ea1m m\u1ed9t s\u1ed1 ti\u00eau chu\u1ea9n l\u00fd t\u01b0\u1edfng trong l\u00fd thuy\u1ebft.`,
  `M\u1eb7c d\u00f9 ch\u00fang ta th\u01b0\u1eddng ngh\u0129 d\u00e2n ch\u1ee7 ch\u1ec9 \u0111\u01a1n gi\u1ea3n l\u00e0 \u0111\u1ebfm phi\u1ebfu b\u1ea7u,`,
  `nh\u01b0ng ch\u00fang ta c\u0169ng n\u00ean suy ngh\u0129 k\u1ef9 c\u00e0ng,`,
  `d\u01b0\u1edbi nh\u1eefng ph\u01b0\u01a1ng ph\u00e1p ki\u1ec3m phi\u1ebfu kh\u00e1c nhau,`,
  `ai s\u1ebd \u0111\u01b0\u1ee3c h\u01b0\u1edfng l\u1ee3i. B\u1ea1n \u0111\u00e3 s\u1eb5n s\u00e0ng h\u1ecdc ti\u1ebfp ch\u01b0a?`,
  `H\u00e3y xem nh\u1eefng video n\u00e0y \u0111\u1ec3 th\u1eed th\u00e1ch suy ngh\u0129 c\u1ee7a b\u1ea1n,`,
  `ho\u1eb7c t\u00ecm hi\u1ec3u th\u00eam nh\u1eefng \u0111i\u1ec1u b\u1ea1n ch\u01b0a bi\u1ebft.`,
  `\u0110\u0103ng k\u00fd v\u00e0 gi\u1eef s\u1ef1 t\u00f2 m\u00f2.`,
];

