const TEDED_NEXT_EXTINCTION_ZYMKENZTXD4_TRANSLATIONS = [
  `Kho\u1ea3ng 66 tri\u1ec7u n\u0103m tr\u01b0\u1edbc,`,
  `s\u1ef1 s\u1ed1ng tr\u00ean h\u00e0nh tinh c\u1ee7a ch\u00fang ta \u0111\u00e3 ph\u1ea3i \u0111\u1ed1i m\u1eb7t v\u1edbi m\u1ed9t th\u1ea3m h\u1ecda kinh ho\u00e0ng.`,
  `H\u1ec7 sinh th\u00e1i ph\u1ea3i ch\u1ecbu hai c\u00fa \u0111\u00e1nh l\u1edbn,`,
  `v\u1ee5 phun tr\u00e0o n\u00fai l\u1eeda quy m\u00f4 l\u1edbn \u0111\u00e3 l\u00e0m kh\u00ed quy\u1ec3n tr\u00e0n ng\u1eadp carbon dioxide.`,
  `\u0110\u1ed3ng th\u1eddi, m\u1ed9t ti\u1ec3u h\u00e0nh tinh c\u00f3 k\u00edch th\u01b0\u1edbc b\u1eb1ng Manhattan \u0111\u00e3 va v\u00e0o Tr\u00e1i \u0110\u1ea5t.`,
  `B\u1ee5i trong kh\u00ed quy\u1ec3n \u0111\u00e3 \u1ea3nh h\u01b0\u1edfng nghi\u00eam tr\u1ecdng \u0111\u1ebfn qu\u00e1 tr\u00ecnh quang h\u1ee3p c\u1ee7a nhi\u1ec1u lo\u00e0i th\u1ef1c v\u1eadt.`,
  `N\u1ea1n \u0111\u00f3i ho\u00e0nh h\u00e0nh kh\u1eafp n\u01a1i,`,
  `c\u1ea3 \u0111\u1ed9ng v\u1eadt \u0103n c\u1ecf v\u00e0 \u0111\u1ed9ng v\u1eadt \u0103n th\u1ecbt ch\u00fang.`,
  `Trong m\u1ed9t th\u1eddi gian r\u1ea5t ng\u1eafn,`,
  `ba ph\u1ea7n t\u01b0 c\u00e1c lo\u00e0i tr\u00ean th\u1ebf gi\u1edbi \u0111\u00e3 tuy\u1ec7t ch\u1ee7ng.`,
  `Nhi\u1ec1u lo\u00e0i kh\u1ee7ng long kh\u1ed5ng l\u1ed3,`,
  `kh\u1ee7ng long bay (Pterosaurs), \u0111\u1ed9ng v\u1eadt th\u00e2n m\u1ec1m c\u00f3 v\u1ecf (Ammonites) v\u00e0 c\u00e1c lo\u00e0i b\u00f2 s\u00e1t bi\u1ec3n \u0111\u00e3 bi\u1ebfn m\u1ea5t trong ti\u1ec1n s\u1eed.`,
  `Kh\u1ee7ng long c\u00f3 v\u1ebb \u0111\u1eb7c bi\u1ec7t k\u00e9m may m\u1eafn,`,
  `nh\u01b0ng \u0111\u00e2y l\u00e0 quy lu\u1eadt sinh t\u1ed3n c\u1ee7a k\u1ebb m\u1ea1nh trong l\u1ecbch s\u1eed Tr\u00e1i \u0110\u1ea5t,`,
  `v\u00e0 \u0111i\u1ec1u \u0111\u00f3 v\u1eabn ti\u1ebfp di\u1ec5n cho \u0111\u1ebfn ng\u00e0y nay.`,
  `M\u00f4i tr\u01b0\u1eddng thay \u0111\u1ed5i,`,
  `\u0111\u1ea9y m\u1ed9t s\u1ed1 lo\u00e0i ra kh\u1ecfi v\u00f9ng tho\u1ea3i m\u00e1i c\u1ee7a ch\u00fang,`,
  `\u0111\u1ed3ng th\u1eddi t\u1ea1o ra c\u01a1 h\u1ed9i m\u1edbi cho c\u00e1c lo\u00e0i kh\u00e1c.`,
  `C\u00e1c lo\u00e0i x\u00e2m l\u1ea5n \u0111\u00e3 \u0111\u00e1nh b\u1ea1i c\u00e1c lo\u00e0i b\u1ea3n \u0111\u1ecba trong m\u00f4i tr\u01b0\u1eddng s\u1ed1ng m\u1edbi.`,
  `\u0110\u00f4i khi, to\u00e0n b\u1ed9 m\u1ed9t lo\u00e0i b\u1ecb x\u00f3a s\u1ed5.`,
  `Do quy lu\u1eadt k\u1ebb m\u1ea1nh s\u1ed1ng s\u00f3t,`,
  `\u0111\u00f4i khi nh\u1eefng thay \u0111\u1ed5i m\u00f4i tr\u01b0\u1eddng \u0111\u1ed9t ng\u1ed9t,`,
  `khi\u1ebfn h\u1ea7u h\u1ebft c\u00e1c sinh v\u1eadt kh\u00f4ng k\u1ecbp t\u1ef1 \u0111i\u1ec1u ch\u1ec9nh,`,
  `d\u1eabn \u0111\u1ebfn h\u00e0ng ng\u00e0n lo\u00e0i b\u1ecb tuy\u1ec7t ch\u1ee7ng trong c\u00e1c bi\u1ebfn \u0111\u1ed5i \u0111\u1ecba ch\u1ea5t \u0111\u1ed9t ng\u1ed9t.`,
  `Ch\u00fang ta g\u1ecdi \u0111\u00f3 l\u00e0 s\u1ef1 ki\u1ec7n tuy\u1ec7t ch\u1ee7ng h\u00e0ng lo\u1ea1t.`,
  `M\u1eb7c d\u00f9 nh\u1eefng s\u1ef1 ki\u1ec7n n\u00e0y r\u1ea5t hi\u1ebfm,`,
  `c\u00e1c nh\u00e0 c\u1ed5 sinh v\u1eadt h\u1ecdc \u0111\u00e3 c\u00f3 th\u1ec3 x\u00e1c \u0111\u1ecbnh \u0111\u01b0\u1ee3c m\u1ed9t v\u00e0i tr\u01b0\u1eddng h\u1ee3p t\u1eeb nh\u1eefng thay \u0111\u1ed5i l\u1edbn trong h\u00f3a th\u1ea1ch.`,
  `V\u00ed d\u1ee5, h\u00f3a th\u1ea1ch c\u1ee7a m\u1ed9t s\u1ed1 lo\u00e0i \u0111\u1ed9t nhi\u00ean bi\u1ebfn m\u1ea5t sau m\u1ed9t v\u00e0i l\u1edbp \u0111\u1ecba ch\u1ea5t.`,
  `Ch\u00fang ta s\u1eed d\u1ee5ng nh\u1eefng s\u1ef1 ki\u1ec7n tuy\u1ec7t ch\u1ee7ng h\u00e0ng lo\u1ea1t n\u00e0y \u0111\u1ec3 ph\u00e2n chia l\u1ecbch s\u1eed Tr\u00e1i \u0110\u1ea5t th\u00e0nh c\u00e1c th\u1eddi k\u1ef3 kh\u00e1c nhau.`,
  `M\u1eb7c d\u00f9 s\u1ef1 bi\u1ebfn m\u1ea5t c\u1ee7a kh\u1ee7ng long l\u00e0 s\u1ef1 ki\u1ec7n tuy\u1ec7t ch\u1ee7ng h\u00e0ng lo\u1ea1t n\u1ed5i ti\u1ebfng nh\u1ea5t,`,
  `Nh\u01b0ng s\u1ef1 ki\u1ec7n \u0111\u1ea1i tuy\u1ec7t ch\u1ee7ng l\u1edbn nh\u1ea5t \u0111\u00e3 x\u1ea3y ra tr\u01b0\u1edbc th\u1eddi kh\u1ee7ng long,`,
  `c\u00e1ch \u0111\u00e2y 252 tri\u1ec7u n\u0103m.`,
  `Gi\u1eefa th\u1eddi k\u1ef3 Permi v\u00e0 Trias,`,
  `c\u00e1c l\u1ee5c \u0111\u1ecba tr\u00ean Tr\u00e1i \u0110\u1ea5t \u0111\u00e3 h\u1ee3p nh\u1ea5t th\u00e0nh m\u1ed9t si\u00eau l\u1ee5c \u0111\u1ecba kh\u1ed5ng l\u1ed3 t\u00ean l\u00e0 Pangea.`,
  `Do \u0111\u1ea5t li\u1ec1n \u0111\u1ea7y sa m\u1ea1c,`,
  `trong qu\u00e1 tr\u00ecnh h\u1ee3p nh\u1ea5t,`,
  `nh\u1eefng b\u00e3i c\u00e1t t\u00edch t\u1ee5 \u0111\u00e3 ch\u00f4n v\u00f9i nhi\u1ec1u v\u00f9ng bi\u1ec3n nhi\u1ec7t \u0111\u1edbi n\u00f4ng n\u01a1i nhi\u1ec1u sinh v\u1eadt sinh s\u1ed1ng.`,
  `N\u00fai l\u1eeda kh\u1ed5ng l\u1ed3 phun tr\u00e0o kh\u1eafp Siberia,`,
  `nhi\u1ec7t \u0111\u1ed9 cao k\u00e9o d\u00e0i g\u00e2y ra hi\u1ec7u \u1ee9ng nh\u00e0 k\u00ednh quy m\u00f4 l\u1edbn.`,
  `Nh\u1eefng th\u1ea3m h\u1ecda n\u00e0y \u0111\u00e3 khi\u1ebfn 95% sinh v\u1eadt bi\u1ec3n b\u1ecb tuy\u1ec7t ch\u1ee7ng.`,
  `Tr\u00ean \u0111\u1ea5t li\u1ec1n, c\u00e1c lo\u00e0i b\u00f2 s\u00e1t k\u1ef7 Permi \u0111\u00e3 \u0111\u01b0\u1ee3c thay th\u1ebf b\u1eb1ng nh\u1eefng lo\u00e0i kh\u1ee7ng long m\u00e0 ch\u00fang ta bi\u1ebft ng\u00e0y nay.`,
  `Tuy nhi\u00ean, s\u1ef1 ki\u1ec7n tuy\u1ec7t ch\u1ee7ng h\u00e0ng lo\u1ea1t kh\u00f4ng ch\u1ec9 l\u00e0 qu\u00e1 kh\u1ee9 xa x\u00f4i.`,
  `Trong v\u00e0i tri\u1ec7u n\u0103m qua,`,
  `s\u1ef1 dao \u0111\u1ed9ng kh\u1ed5ng l\u1ed3 c\u1ee7a c\u00e1c kh\u1ed1i b\u0103ng \u1edf hai c\u1ef1c Tr\u00e1i \u0110\u1ea5t \u0111\u00e3 g\u00e2y ra s\u1ef1 t\u0103ng gi\u1ea3m m\u1ef1c n\u01b0\u1edbc bi\u1ec3n,`,
  `c\u0169ng nh\u01b0 s\u1ef1 thay \u0111\u1ed5i kh\u00ed h\u1eadu v\u00e0 h\u1ea3i l\u01b0u.`,
  `Khi b\u0103ng gi\u00e1 lan r\u1ed9ng,`,
  `r\u00fat \u0111i v\u00e0 ph\u1ee5c h\u1ed3i,`,
  `m\u1ed9t s\u1ed1 lo\u00e0i \u0111\u1ed9ng v\u1eadt c\u00f3 th\u1ec3 th\u00edch nghi v\u1edbi nh\u1eefng thay \u0111\u1ed5i n\u00e0y,`,
  `ho\u1eb7c di c\u01b0 \u0111\u1ebfn nh\u1eefng n\u01a1i th\u00edch h\u1ee3p h\u01a1n.`,
  `Tuy nhi\u00ean, nh\u1eefng lo\u00e0i kh\u00e1c nh\u01b0 l\u01b0\u1eddi \u0111\u1ea5t kh\u1ed5ng l\u1ed3,`,
  `linh c\u1ea9u kh\u1ed5ng l\u1ed3 v\u00e0 voi ma m\u00fat \u0111\u00e3 tuy\u1ec7t ch\u1ee7ng.`,
  `S\u1ef1 tuy\u1ec7t ch\u1ee7ng c\u1ee7a nh\u1eefng lo\u00e0i \u0111\u1ed9ng v\u1eadt c\u00f3 v\u00fa kh\u1ed5ng l\u1ed3 n\u00e0y \u0111\u1ed3ng th\u1eddi v\u1edbi s\u1ef1 thay \u0111\u1ed5i kh\u00ed h\u1eadu v\u00e0 h\u1ec7 sinh th\u00e1i,`,
  `t\u1ea5t c\u1ea3 \u0111\u1ec1u do b\u0103ng tan ch\u1ea3y.`,
  `M\u1ed9t hi\u1ec7u \u1ee9ng k\u00e9p kh\u00e1c l\u00e0,`,
  `s\u1ef1 ti\u1ebfn h\u00f3a c\u1ee7a m\u1ed9t s\u1ed1 lo\u00e0i ng\u01b0\u1eddi nguy\u00ean th\u1ee7y c\u00f3 ngu\u1ed3n g\u1ed1c t\u1eeb ch\u00e2u Phi c\u00e1ch \u0111\u00e2y 150.000 n\u0103m.`,
  `Trong qu\u00e1 tr\u00ecnh th\u00edch nghi v\u1edbi m\u00f4i tr\u01b0\u1eddng m\u1edbi,`,
  `h\u1ecd \u0111\u00e3 t\u1ea1o ra nh\u1eefng c\u00f4ng c\u1ee5 v\u00e0 ph\u01b0\u01a1ng ph\u00e1p m\u1edbi \u0111\u1ec3 thu th\u1eadp th\u1ee9c \u0103n v\u00e0 s\u0103n b\u1eafn.`,
  `Con ng\u01b0\u1eddi c\u00f3 th\u1ec3 kh\u00f4ng tr\u1ef1c ti\u1ebfp g\u00e2y ra s\u1ef1 tuy\u1ec7t ch\u1ee7ng c\u1ee7a nh\u1eefng lo\u00e0i \u0111\u1ed9ng v\u1eadt l\u1edbn n\u00e0y,`,
  `v\u00ec m\u1ed9t s\u1ed1 lo\u00e0i trong s\u1ed1 \u0111\u00f3 \u0111\u00e3 chung s\u1ed1ng v\u1edbi ch\u00fang ta h\u00e0ng ngh\u00ecn n\u0103m.`,
  `Nh\u01b0ng r\u00f5 r\u00e0ng h\u00f4m nay,`,
  `C\u00e1c c\u00f4ng c\u1ee5 v\u00e0 ph\u01b0\u01a1ng ph\u00e1p s\u0103n b\u1eaft c\u1ee7a ch\u00fang ta \u0111\u00e3 tr\u1edf n\u00ean hi\u1ec7u qu\u1ea3 \u0111\u1ebfn m\u1ee9c`,
  `con ng\u01b0\u1eddi kh\u00f4ng c\u00f2n c\u1ea7n ph\u1ea3i th\u00edch nghi v\u1edbi m\u00f4i tr\u01b0\u1eddng t\u1ef1 nhi\u00ean n\u1eefa,`,
  `m\u00e0 thay v\u00e0o \u0111\u00f3 b\u1eaft \u0111\u1ea7u thay \u0111\u1ed5i m\u00f4i tr\u01b0\u1eddng t\u1ef1 nhi\u00ean.`,
  `S\u1ef1 tuy\u1ec7t ch\u1ee7ng c\u1ee7a c\u00e1c lo\u00e0i tr\u1edf th\u00e0nh m\u1ed9t hi\u1ec7n t\u01b0\u1ee3ng b\u00ecnh th\u01b0\u1eddng trong b\u1ed1i c\u1ea3nh h\u1ec7 sinh th\u00e1i ng\u00e0y nay,`,
  `nh\u01b0ng nghi\u00ean c\u1ee9u cho th\u1ea5y,`,
  `t\u1ef7 l\u1ec7 tuy\u1ec7t ch\u1ee7ng c\u1ee7a nhi\u1ec1u sinh v\u1eadt ng\u00e0y nay cao h\u01a1n h\u00e0ng tr\u0103m \u0111\u1ebfn h\u00e0ng ngh\u00ecn l\u1ea7n so v\u1edbi t\u1ef7 l\u1ec7 tuy\u1ec7t ch\u1ee7ng t\u1ef1 nhi\u00ean.`,
  `Con ng\u01b0\u1eddi c\u00f3 kh\u1ea3 n\u0103ng tuy\u1ec7t di\u1ec7t c\u00e1c lo\u00e0i tr\u00ean quy m\u00f4 l\u1edbn,`,
  `c\u0169ng c\u00f3 th\u1ec3 d\u00f9ng kh\u1ea3 n\u0103ng t\u01b0\u01a1ng t\u1ef1 \u0111\u1ec3 ng\u0103n ch\u1eb7n \u0111i\u1ec1u \u0111\u00f3 x\u1ea3y ra.`,
  `Th\u00f4ng qua vi\u1ec7c t\u00ecm hi\u1ec3u v\u1ec1 s\u1ef1 tuy\u1ec7t ch\u1ee7ng c\u1ee7a c\u00e1c lo\u00e0i v\u1eadt,`,
  `ch\u00fang ta s\u1ebd nh\u1eadn ra t\u00e1c \u0111\u1ed9ng c\u1ee7a s\u1ef1 thay \u0111\u1ed5i m\u00f4i tr\u01b0\u1eddng ng\u00e0y nay.`,
  `S\u1eed d\u1ee5ng nh\u1eefng ki\u1ebfn th\u1ee9c n\u00e0y \u0111\u1ec3 gi\u1ea3m thi\u1ec3u t\u00e1c \u0111\u1ed9ng c\u1ee7a ch\u00fang ta \u0111\u1ed1i v\u1edbi c\u00e1c lo\u00e0i v\u1eadt kh\u00e1c,`,
  `ch\u00fang ta c\u00f3 th\u1ec3 thay \u0111\u1ed5i t\u00e1c \u0111\u1ed9ng c\u1ee7a con ng\u01b0\u1eddi \u0111\u1ed1i v\u1edbi th\u1ebf gi\u1edbi t\u1ef1 nhi\u00ean,`,
  `t\u1eeb s\u1ee9c t\u00e0n ph\u00e1 nh\u01b0 thi\u00ean th\u1ea1ch va v\u00e0o Tr\u00e1i \u0111\u1ea5t, th\u00e0nh m\u1ed9t t\u01b0\u01a1ng lai \u0111a d\u1ea1ng sinh h\u1ecdc c\u00f9ng t\u1ed3n t\u1ea1i h\u00e0i h\u00f2a.`,
  `Vi\u1ec7c b\u1ea3o v\u1ec7 v\u00e0 g\u00ecn gi\u1eef thi\u00ean nhi\u00ean ph\u1ea3i tr\u1edf th\u00e0nh \u01b0u ti\u00ean h\u00e0ng \u0111\u1ea7u c\u1ee7a m\u1ecdi qu\u1ed1c gia,`,
  `c\u00f4ng ty v\u00e0 c\u1ed9ng \u0111\u1ed3ng tr\u00ean th\u1ebf gi\u1edbi.`,
  `N\u1ebfu b\u1ea1n mu\u1ed1n bi\u1ebft c\u00e1c b\u01b0\u1edbc c\u1ee5 th\u1ec3 b\u1ea1n c\u00f3 th\u1ec3 th\u1ef1c hi\u1ec7n ngay b\u00e2y gi\u1edd \u0111\u1ec3 gi\u00fap \u0111\u1ea1t \u0111\u01b0\u1ee3c m\u1ee5c ti\u00eau n\u00e0y,`,
  `vui l\u00f2ng truy c\u1eadp i.tai.com/earthgu.`,
];

