const TEDED_NOSTALGIA_KXK9MMPYTGU_TRANSLATIONS = [
  `V\u00e0o cu\u1ed1i th\u1ebf k\u1ef7 17, m\u1ed9t sinh vi\u00ean y khoa t\u00ean Johannes Hofer \u0111\u00e3 nh\u1eadn th\u1ea5y m\u1ed9t c\u0103n b\u1ec7nh l\u1ea1,`,
  `\u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn nh\u1eefng l\u00ednh \u0111\u00e1nh thu\u00ea Th\u1ee5y S\u0129 \u0111ang l\u00e0m vi\u1ec7c \u1edf n\u01b0\u1edbc ngo\u00e0i.`,
  `Tri\u1ec7u ch\u1ee9ng c\u1ee7a b\u1ec7nh bao g\u1ed3m m\u1ec7t m\u1ecfi,`,
  `m\u1ea5t ng\u1ee7, nh\u1ecbp tim kh\u00f4ng \u0111\u1ec1u,`,
  `kh\u00f3 ti\u00eau v\u00e0 s\u1ed1t cao,`,
  `nh\u1eefng ng\u01b0\u1eddi l\u00ednh n\u00e0y th\u01b0\u1eddng ph\u1ea3i gi\u1ea3i ng\u0169.`,
  `Hofer ph\u00e1t hi\u1ec7n ra r\u1eb1ng nguy\u00ean nh\u00e2n b\u1ec7nh c\u1ee7a h\u1ecd kh\u00f4ng ph\u1ea3i l\u00e0 b\u1ec7nh t\u1eadt th\u1ec3 ch\u1ea5t,`,
  `m\u00e0 l\u00e0 n\u1ed7i nh\u1edb nh\u00e0 m\u00e3nh li\u1ec7t.`,
  `\u00d4ng \u0111\u1eb7t t\u00ean cho t\u00ecnh tr\u1ea1ng n\u00e0y l\u00e0 'nostalgia', t\u1eeb 'nostos' trong ti\u1ebfng Hy L\u1ea1p c\u00f3 ngh\u0129a l\u00e0 'tr\u1edf v\u1ec1 nh\u00e0',`,
  `v\u00e0 'algia' c\u00f3 ngh\u0129a l\u00e0 \u0111au \u0111\u1edbn v\u00e0 khao kh\u00e1t.`,
  `Ban \u0111\u1ea7u, nostalgia \u0111\u01b0\u1ee3c cho l\u00e0 m\u1ed9t c\u0103n b\u1ec7nh ch\u1ec9 x\u1ea3y ra \u1edf Th\u1ee5y S\u0129,`,
  `m\u1ed9t s\u1ed1 b\u00e1c s\u0129 cho r\u1eb1ng ti\u1ebfng chu\u00f4ng b\u00f2 li\u00ean t\u1ee5c \u1edf d\u00e3y Alps \u0111\u00e3 g\u00e2y ra ch\u1ea5n th\u01b0\u01a1ng m\u00e0ng x\u01b0\u01a1ng v\u00e0 n\u00e3o.`,
  `C\u00e1c ch\u1ec9 huy th\u1eadm ch\u00ed c\u00f2n c\u1ea5m binh l\u00ednh c\u1ee7a h\u1ecd h\u00e1t c\u00e1c b\u00e0i h\u00e1t truy\u1ec1n th\u1ed1ng c\u1ee7a Th\u1ee5y S\u0129,`,
  `\u0111\u1ec3 ng\u0103n h\u1ecd t\u1ef1 \u00fd r\u1eddi qu\u00e2n ho\u1eb7c t\u1ef1 s\u00e1t.`,
  `Tuy nhi\u00ean, v\u1edbi s\u1ef1 to\u00e0n c\u1ea7u h\u00f3a c\u1ee7a di c\u01b0, ng\u01b0\u1eddi ta nh\u1eadn th\u1ea5y nostalgia xu\u1ea5t hi\u1ec7n \u1edf nhi\u1ec1u nh\u00f3m ng\u01b0\u1eddi kh\u00e1c nhau,`,
  `Th\u00ec ra b\u1ea5t c\u1ee9 ai xa qu\u00ea h\u01b0\u01a1ng l\u00e2u ng\u00e0y \u0111\u1ec1u d\u1ec5 m\u1eafc ch\u1ee9ng t\u01b0\u01a1ng t\u01b0.`,
  `Nh\u01b0ng \u0111\u1ebfn \u0111\u1ea7u th\u1ebf k\u1ef7 20,`,
  `c\u00e1c chuy\u00ean gia kh\u00f4ng c\u00f2n coi \u0111\u00f3 l\u00e0 m\u1ed9t b\u1ec7nh th\u1ea7n kinh n\u1eefa,`,
  `m\u00e0 coi \u0111\u00f3 l\u00e0 m\u1ed9t b\u1ec7nh t\u00e2m l\u00fd t\u01b0\u01a1ng t\u1ef1 nh\u01b0 tr\u1ea7m c\u1ea3m.`,
  `C\u00e1c nh\u00e0 t\u00e2m l\u00fd h\u1ecdc th\u1eddi \u0111\u00f3 suy \u0111o\u00e1n r\u1eb1ng,`,
  `n\u00f3 ph\u1ea3n \u00e1nh s\u1ef1 kh\u00f3 kh\u0103n khi qu\u00ean \u0111i th\u1eddi th\u01a1 \u1ea5u,`,
  `hay th\u1eadm ch\u00ed l\u00e0 khao kh\u00e1t \u0111\u01b0\u1ee3c tr\u1edf v\u1ec1 tu\u1ed5i th\u01a1 \u1ea5u c\u1ee7a m\u1ed9t ng\u01b0\u1eddi.`,
  `Nh\u01b0ng trong v\u00e0i th\u1eadp k\u1ef7 ti\u1ebfp theo,`,
  `nh\u1eadn th\u1ee9c v\u1ec1 n\u1ed7i nh\u1edb \u0111\u00e3 thay \u0111\u1ed5i \u1edf hai kh\u00eda c\u1ea1nh quan tr\u1ecdng,`,
  `\u00fd ngh\u0129a c\u1ee7a n\u00f3 \u0111\u00e3 m\u1edf r\u1ed9ng t\u1eeb vi\u1ec7c ch\u1ec9 t\u00ecnh c\u1ea3m nh\u1edb nh\u00e0 sang m\u1ed9t n\u1ed7i khao kh\u00e1t chung v\u1ec1 qu\u00e1 kh\u1ee9.`,
  `H\u01a1n n\u1eefa, kh\u00f4ng ph\u1ea3i l\u00e0 m\u1ed9t c\u0103n b\u1ec7nh \u0111\u00e1ng gh\u00e9t,`,
  `n\u00f3 b\u1eaft \u0111\u1ea7u \u0111\u01b0\u1ee3c coi l\u00e0 m\u1ed9t tr\u1ea3i nghi\u1ec7m v\u1eeba cay \u0111\u1eafng v\u1eeba th\u00fa v\u1ecb.`,
  `C\u00f3 l\u1ebd v\u00ed d\u1ee5 n\u1ed5i ti\u1ebfng li\u00ean quan \u0111\u1ebfn \u0111i\u1ec1u n\u00e0y,`,
  `ch\u00ednh l\u00e0 nh\u00e0 v\u0103n ng\u01b0\u1eddi Ph\u00e1p Marcel Proust.`,
  `\u00d4ng \u0111\u00e3 mi\u00eau t\u1ea3 vi\u1ec7c n\u1ebfm th\u1eed m\u1ed9t chi\u1ebfc b\u00e1nh Madeleine m\u00e0 t\u1eeb nh\u1ecf \u00f4ng ch\u01b0a t\u1eebng \u0103n l\u1ea1i,`,
  `l\u00e0 nh\u1eefng g\u00ec \u0111\u00e3 k\u00edch ho\u1ea1t c\u00e1c li\u00ean t\u01b0\u1edfng c\u1ea3m gi\u00e1c \u1ea5m \u00e1p v\u00e0 m\u1ea1nh m\u1ebd c\u1ee7a anh \u1ea5y.`,
  `V\u1eady \u0111i\u1ec1u g\u00ec \u0111\u00e3 g\u00e2y ra s\u1ef1 thay \u0111\u1ed5i l\u1edbn trong c\u00e1ch ch\u00fang ta nh\u00ecn nh\u1eadn hi\u1ec7n t\u01b0\u1ee3ng ho\u00e0i ni\u1ec7m?`,
  `C\u00f4ng ngh\u1ec7 ch\u1eafc ch\u1eafn c\u00f3 li\u00ean quan \u0111\u1ebfn \u0111i\u1ec1u n\u00e0y,`,
  `v\u00e0 t\u00e2m l\u00fd h\u1ecdc \u0111\u00e3 thay \u0111\u1ed5i t\u1eeb l\u00fd thuy\u1ebft thu\u1ea7n t\u00fay sang th\u1ef1c h\u00e0nh quan s\u00e1t c\u00f3 h\u1ec7 th\u1ed1ng v\u00e0 th\u1eadn tr\u1ecdng h\u01a1n.`,
  `V\u00ec v\u1eady, c\u00e1c chuy\u00ean gia ph\u00e1t hi\u1ec7n ra r\u1eb1ng nhi\u1ec1u tri\u1ec7u ch\u1ee9ng ti\u00eau c\u1ef1c c\u00f3 th\u1ec3 ch\u1ec9 li\u00ean quan \u0111\u1ebfn n\u1ed7i nh\u1edb nh\u00e0,`,
  `c\u00f3 th\u1ec3 ch\u1ec9 li\u00ean quan \u0111\u1ebfn ho\u00e0i ni\u1ec7m,`,
  `ch\u1ee9 kh\u00f4ng ph\u1ea3i do n\u00f3 g\u00e2y ra.`,
  `Tr\u00ean th\u1ef1c t\u1ebf, ngo\u1ea1i tr\u1eeb khi \u1edf trong tr\u1ea1ng th\u00e1i c\u1ea3m x\u00fac ph\u1ee9c t\u1ea1p,`,
  `M\u1ed9t tr\u1ea1ng th\u00e1i ch\u1ee9a \u0111\u1ef1ng s\u1ef1 m\u1ea5t m\u00e1t v\u00e0 \u0111au bu\u1ed3n,`,
  `Ho\u00e0i ni\u1ec7m kh\u00f4ng ph\u1ea3i l\u00fac n\u00e0o c\u0169ng khi\u1ebfn ng\u01b0\u1eddi ta ch\u00ecm \u0111\u1eafm trong nh\u1eefng c\u1ea3m x\u00fac ti\u00eau c\u1ef1c.`,
  `Ng\u01b0\u1ee3c l\u1ea1i, n\u1ebfu cho ph\u00e9p m\u1ed7i c\u00e1 nh\u00e2n ghi l\u1ea1i \u0111\u1ed1i v\u1edbi ri\u00eang h\u1ecd,`,
  `Nh\u1eefng tr\u1ea3i nghi\u1ec7m \u00fd ngh\u0129a v\u00e0 \u0111\u1eb7c bi\u1ec7t v\u1edbi ng\u01b0\u1eddi kh\u00e1c,`,
  `V\u1eady th\u00ec c\u1ea3m gi\u00e1c ho\u00e0i ni\u1ec7m c\u00f3 l\u1ee3i cho s\u1ee9c kh\u1ecfe tinh th\u1ea7n.`,
  `Nghi\u00ean c\u1ee9u cho th\u1ea5y g\u1ee3i l\u00ean c\u1ea3m gi\u00e1c ho\u00e0i ni\u1ec7m gi\u00fap n\u00e2ng cao l\u00f2ng t\u1ef1 tr\u1ecdng v\u00e0 c\u1ea3m gi\u00e1c th\u00e2n thu\u1ed9c c\u1ee7a con ng\u01b0\u1eddi,`,
  `th\u00fac \u0111\u1ea9y tr\u01b0\u1edfng th\u00e0nh v\u1ec1 t\u00e2m l\u00fd,`,
  `th\u1eadm ch\u00ed khi\u1ebfn h\u1ecd tr\u1edf n\u00ean nh\u00e2n \u00e1i h\u01a1n.`,
  `Do \u0111\u00f3, h\u1ed3i t\u01b0\u1edfng kh\u00f4ng ph\u1ea3i l\u00e0 nguy\u00ean nh\u00e2n g\u00e2y ra \u0111au kh\u1ed5 v\u1ec1 m\u1eb7t t\u00e2m l\u00fd,`,
  `m\u00e0 c\u00f3 th\u1ec3 l\u00e0 m\u1ed9t c\u01a1 ch\u1ebf \u0111\u1ed1i ph\u00f3 gi\u00fap ph\u1ee5c h\u1ed3i.`,
  `Ch\u1eb3ng h\u1ea1n, khi con ng\u01b0\u1eddi r\u01a1i v\u00e0o tr\u1ea1ng th\u00e1i c\u1ea3m x\u00fac ti\u00eau c\u1ef1c,`,
  `h\u1ecd c\u00f3 xu h\u01b0\u1edbng t\u1ef1 nhi\u00ean nh\u1edb v\u1ec1 qu\u00e1 kh\u1ee9,`,
  `nh\u1edd \u0111\u00f3 gi\u1ea3m b\u1edbt \u0111au kh\u1ed5 v\u00e0 ph\u1ee5c h\u1ed3i s\u1ee9c kh\u1ecfe.`,
  `Ng\u00e0y nay, ho\u00e0i ni\u1ec7m d\u01b0\u1eddng nh\u01b0 hi\u1ec7n di\u1ec7n \u1edf kh\u1eafp m\u1ecdi n\u01a1i,`,
  `m\u1ed9t ph\u1ea7n v\u00ec c\u00e1c nh\u00e0 qu\u1ea3ng c\u00e1o \u0111\u00e3 kh\u00e1m ph\u00e1 ra s\u1ee9c \u1ea3nh h\u01b0\u1edfng to l\u1edbn c\u1ee7a n\u00f3.`,
  `Khi n\u00f3 \u0111\u01b0\u1ee3c d\u00f9ng nh\u01b0 m\u1ed9t c\u00f4ng c\u1ee5 ti\u1ebfp th\u1ecb,`,
  `ng\u01b0\u1eddi ta d\u1ec5 d\u00e0ng coi ho\u00e0i ni\u1ec7m l\u00e0 d\u1ea5u hi\u1ec7u cho th\u1ea5y ch\u00fang ta \u0111ang ch\u00ecm \u0111\u1eafm trong qu\u00e1 kh\u1ee9,`,
  `nh\u01b0ng \u0111\u00f3 kh\u00f4ng th\u1ef1c s\u1ef1 l\u00e0 m\u1ee5c \u0111\u00edch c\u1ee7a n\u00f3.`,
  `Thay v\u00e0o \u0111\u00f3,`,
  `ho\u00e0i ni\u1ec7m gi\u00fap ch\u00fang ta ghi nh\u1edb r\u1eb1ng,`,
  `cu\u1ed9c s\u1ed1ng c\u1ee7a ch\u00fang ta c\u00f3 th\u1ec3 c\u00f3 \u00fd ngh\u0129a v\u00e0 gi\u00e1 tr\u1ecb,`,
  `gi\u00fap ch\u00fang ta t\u00ecm th\u1ea5y ni\u1ec1m tin,`,
  `T\u00ecm \u0111\u01b0\u1ee3c \u0111\u1ed9ng l\u1ef1c \u0111\u1ec3 \u0111\u1ed1i m\u1eb7t v\u1edbi th\u1eed th\u00e1ch trong t\u01b0\u01a1ng lai.`,
  `H\u00e3y \u0111\u1ea3m b\u1ea3o b\u1ea1n \u0111\u00e3 \u0111\u0103ng k\u00fd k\u00eanh n\u00e0y,`,
  `\u0110\u1ec3 kh\u00f4ng b\u1ecf l\u1ee1 c\u01a1 h\u1ed9i ti\u1ebfp thu nh\u1eefng \u0111i\u1ec1u m\u1edbi m\u1ebb.`,
];

